 const list=value=>Array.isArray(value)?value:[];
 function el(tag,props,...children){const node=document.createElement(tag);for(const [key,value] of Object.entries(props||{})){if(key==='class')node.className=value;else if(key==='text')node.textContent=value;else if(key==='htmlFor')node.htmlFor=value;else if(key.startsWith('data-'))node.setAttribute(key,value);else node[key]=value;}for(const child of children.flat()){if(child===null||child===undefined)continue;node.append(typeof child==='string'?document.createTextNode(child):child);}return node;}
 function button(label,className='ms-mini',onClick,aria=''){const node=el('button',{type:'button',className,text:label});if(aria)node.setAttribute('aria-label',aria);node.addEventListener('click',onClick);return node;}
 function input({type='text',value='',maxLength,placeholder='',checked=false}={}){const node=el('input',{type,value,placeholder});if(maxLength)node.maxLength=maxLength;if(type==='checkbox')node.checked=checked;return node;}
 function label(title,note,control){const titleNode=el('span',null,el('b',{text:title}),note?el('small',{text:note}):null);return el('label',{className:'f-field'},titleNode,control);}
 function fieldText(title,note,value,change,{area=false,max=undefined,placeholder='',type='text'}={}){const control=area?el('textarea',{value,placeholder}):input({type,value,placeholder,maxLength:max});if(area){control.rows=4;if(max)control.maxLength=max;}control.addEventListener('input',()=>change(control.type==='checkbox'?control.checked:control.value));return label(title,note,control);}
 function select(options,value,change){const node=el('select');for(const [id,name,disabled] of options){const option=el('option',{value:id,text:name});option.disabled=Boolean(disabled);option.selected=id===value;node.append(option);}node.addEventListener('change',()=>change(node.value));return node;}
 function safeImage(source){if(!source)return null;if(source.kind==='url'&&/^https:\/\//i.test(source.url))return source.url;if(source.kind==='asset'&&/^[A-Za-z0-9_-]{1,48}$/.test(source.assetId))return `${API}/assets/${encodeURIComponent(source.assetId)}`;if(source.kind==='upload'){const upload=state.uploads.get(source.uploadId);if(upload)return `data:${upload.mime};base64,${upload.base64}`;}return null;}
