 function rolePicker(root,title,note,value,change){const box=el('div'),picker=select(roleOptions(value),value,next=>{change(next);manual.querySelector('input').value=next;mark(root);});const truncated=state.data?.rolesTruncated?tr(' Daftar dibatasi 250 role; gunakan ID manual bila role tidak terlihat.',' List limited to 250 roles; use a manual ID if the role is not shown.'):'';box.append(label(title,`${note} ${tr('Daftar berasal dari cache server; izin diperiksa ulang saat action berjalan.','The list comes from the server cache; permissions are checked again when the action runs.')}${truncated}`,picker));const manual=fieldText(`ID ${title.toLowerCase()}`,tr('Opsional: isi ID manual jika role tidak tersedia di daftar.','Optional: enter an ID manually if the role is not in the list.'),value,next=>{change(next);picker.replaceChildren(...roleOptions(next).map(([id,name,disabled])=>{const option=el('option',{value:id,text:name});option.disabled=Boolean(disabled);option.selected=id===next;return option;}));mark(root);},{max:20});box.append(manual);return box;}
