 function drawOutsidePreview(box,blocks){for(const block of list(blocks)){if(block.type==='text')box.append(markdownText(block.content,'ms-outside-text'));else if(block.type==='file')box.append(previewFile(block));else if(block.type==='separator')box.append(el('hr',{className:`ms-discord-separator${block.spacing===2?' large':''}`}));else if(block.type==='media'){const gallery=el('div',{className:'ms-discord-gallery'});for(const item of block.items){const source=safeImage(item.source);if(source)gallery.append(previewImage(item,source));else gallery.append(el('div',{className:'ms-empty',text:tr('Gambar belum dipilih.','No image selected.')}));}box.append(gallery);}else if(block.type==='buttons'){const row=el('div',{className:'ms-discord-buttons ms-outside-buttons'});for(const item of block.buttons)row.append(previewButton(item));box.append(row);}else if(block.type==='select'||block.type==='entity-select'){const menu=el('select',{className:'ms-discord-select',disabled:true});menu.append(el('option',{text:block.placeholder||tr('Pilih…','Select…')}));for(const item of list(block.options))menu.append(el('option',{text:`${item.emoji?item.emoji+' ':''}${item.label||tr('Pilihan','Option')}`}));box.append(menu);}}}
 function syncDelivery(root){const channel=$('#msChannel',root),sender=$('#msSender',root),name=$('#msWebhookName',root),avatar=$('#msWebhookAvatar',root),identity=$('#msIdentityFields',root),note=$('#msEditingNote',root);if(!channel)return;channel.replaceChildren(el('option',{value:'',text:tr('Pilih channel tujuan','Choose destination channel')}));for(const item of list(state.data?.channels)){const option=el('option',{value:item.id,text:`# ${item.name}${state.delivery.sender==='webhook'&&!item.webhookUsable?tr(' (izin webhook kurang)',' (missing webhook permission)'):''}`});option.disabled=state.delivery.sender==='webhook'?!item.webhookUsable:!item.botUsable;option.selected=item.id===state.delivery.channelId;channel.append(option);}sender.value=state.delivery.sender;name.value=state.delivery.identity.name||'';avatar.value=state.delivery.identity.avatarUrl||'';identity.hidden=state.delivery.sender!=='webhook';const template=$('#msTemplateName',root);if(template&&document.activeElement!==template)template.value=state.templateName||'';const editing=Boolean(state.messageId);channel.disabled=editing;sender.disabled=editing;name.disabled=editing;avatar.disabled=editing;note.hidden=!editing;if(editing)note.textContent=tr('Mengedit pesan yang tercatat. Channel dan mode pengirim tidak dapat diganti; gunakan Kirim salinan untuk pesan baru.','Editing a recorded message. Channel and sender mode cannot be changed; use Send copy for a new message.');const send=$('#msSend',root),update=$('#msUpdate',root),copy=$('#msSendCopy',root),remove=$('#msDeleteMessage',root),forget=$('#msForgetMessage',root);if(send)send.hidden=editing;if(update)update.hidden=!editing;if(copy)copy.hidden=!editing;if(remove)remove.hidden=!editing;if(forget)forget.hidden=!editing;const manage=$('#msManageMessage',root);if(manage)manage.hidden=!editing;}
 function drawEditor(root){drawTree(root);drawInspector(root);drawPreview(root);syncDelivery(root);setStatus(root,state.status||tr('Belum disimpan.','Not saved yet.'));}
 async function reload(root,tab){state.data=await request('/');if(tab==='library')drawLibrary(root);else{drawEditor(root);syncRecurringTemplates(root);}}
 function editorMarkup(){return `<div class="ms-shell" id="messageStudio"><section class="f-panel"><div class="f-panel-head"><div><h2>Composer container</h2><p>${tr('Susun pesan Discord dengan container, teks, media, tombol, dan menu.','Compose Discord messages with containers, text, media, buttons and menus.')}</p></div><span>✦</span></div><div class="ms-top-actions"><button class="f-outline" type="button" id="msNew">${tr('PESAN BARU','NEW MESSAGE')}</button><button class="f-outline" type="button" id="msImport">IMPORT JSON</button><button class="f-outline" type="button" id="msExport">EXPORT JSON</button><button class="f-outline" type="button" id="msAddContainer">+ CONTAINER</button><input class="ms-hidden" type="file" id="msImportFile" accept="application/json,.json"></div><details class="ms-json-panel"><summary>${tr('Buat draf pengumuman dengan AI','Draft an announcement with AI')}</summary><p class="ms-empty">${tr('Khusus owner bot. Poin dikirim ke provider AI dan memakai kuota; jangan masukkan rahasia. AI bisa keliru. Draf tidak dikirim ke Discord otomatis.','Bot owner only. Points are sent to the AI provider and use quota; do not include secrets. AI can be wrong. Drafts are not sent to Discord automatically.')}</p><label for="msAiPoints">${tr('Poin pengumuman','Announcement points')}</label><textarea id="msAiPoints" class="ms-json" rows="3" maxlength="1200" placeholder="${tr('Isi tujuan, waktu dan informasi penting','Enter the purpose, time and important information')}"></textarea><div class="ms-inline-actions"><button class="f-outline" type="button" id="msAiGenerate">${tr('BUAT DRAF AI','CREATE AI DRAFT')}</button></div><label for="msAiDraft">${tr('Draf untuk diperiksa dan disunting','Draft to review and edit')}</label><textarea id="msAiDraft" class="ms-json" rows="6" maxlength="1500"></textarea><div class="ms-inline-actions"><button class="f-outline" type="button" id="msAiApply">${tr('PAKAI DI KOMPONEN TERPILIH','USE IN SELECTED COMPONENT')}</button></div><p id="msAiStatus" class="ms-empty" role="status"></p></details><details class="ms-json-panel"><summary>${tr('Tempel atau salin JSON','Paste or copy JSON')}</summary><p class="ms-empty">${tr('Muat JSON Message Studio atau Discord. Lampiran perlu diunggah ulang.','Load Message Studio or Discord JSON. Attachments must be uploaded again.')}</p><label for="msJsonText" class="ms-json-label">${tr('JSON pesan','Message JSON')}</label><textarea id="msJsonText" class="ms-json" rows="8" spellcheck="false" placeholder="${tr('Tempel JSON di sini','Paste JSON here')}"></textarea><div class="ms-inline-actions"><button class="f-outline" type="button" id="msJsonLoad">${tr('MUAT JSON','LOAD JSON')}</button><button class="f-outline" type="button" id="msJsonShow">${tr('TAMPILKAN JSON EDITOR','SHOW EDITOR JSON')}</button><button class="f-outline" type="button" id="msJsonCopy">${tr('SALIN JSON EDITOR','COPY EDITOR JSON')}</button></div></details><div class="ms-warning">${tr('Webhook dikelola bot; jangan tempel URL atau token webhook. Tombol respons dan menu hanya tersedia dalam mode bot. File maksimal 5 MB; total request maksimal 8 MB termasuk pengkodean.','Webhooks are managed by the bot; do not paste webhook URLs or tokens. Response buttons and menus are available only in bot mode. Files are limited to 5 MB; total request size is limited to 8 MB including encoding.')}</div><div class="ms-delivery"><label class="f-field"><span><b>${tr('Channel tujuan','Destination channel')}</b><small>${tr('Pilih channel teks yang dapat diakses bot.','Choose a text channel accessible to the bot.')}</small></span><select id="msChannel"></select></label><label class="f-field"><span><b>${tr('Mode pengirim','Sender mode')}</b><small>${tr('Akun bot atau webhook yang dibuat bot.','Bot account or bot-created webhook.')}</small></span><select id="msSender"><option value="bot">${tr('Akun ZentixBot','ZentixBot account')}</option><option value="webhook">${tr('Webhook terkelola','Managed webhook')}</option></select></label></div><div id="msIdentityFields" class="ms-delivery"><label class="f-field"><span><b>${tr('Nama webhook','Webhook name')}</b><small>${tr('Opsional, maksimal 80 karakter.','Optional, maximum 80 characters.')}</small></span><input id="msWebhookName" maxlength="80"></label><label class="f-field"><span><b>${tr('Avatar webhook','Webhook avatar')}</b><small>${tr('Opsional, URL HTTPS.','Optional, HTTPS URL.')}</small></span><input id="msWebhookAvatar" maxlength="2000" placeholder="https://…"></label></div><p class="ms-warning" id="msEditingNote" hidden></p><div class="ms-workspace"><aside class="ms-tree"><div class="ms-tree-head"><span>${tr('STRUKTUR PESAN','MESSAGE STRUCTURE')}</span><span>MAX 4</span></div><div class="ms-tree-body" id="msTree"></div></aside><section class="ms-inspector"><div class="ms-inspector-head"><span>${tr('EDITOR KOMPONEN','COMPONENT EDITOR')}</span><span>V2</span></div><div class="ms-inspector-body" id="msInspector"></div></section><aside class="ms-preview"><div class="ms-preview-head"><span>${tr('PREVIEW DISCORD','DISCORD PREVIEW')}</span><span>CONTAINER</span></div><div class="ms-discord" id="msPreview"></div></aside></div><section class="ms-actions" aria-label="${tr('Simpan dan kirim pesan','Save and send message')}"><div class="ms-action-section"><div class="ms-action-heading"><strong>${tr('Simpan template','Save template')}</strong><small>${tr('Simpan susunan untuk digunakan lagi.','Save the layout for reuse.')}</small></div><div class="ms-template-actions"><label class="ms-template-field" for="msTemplateName">${tr('Nama template','Template name')}<input id="msTemplateName" maxlength="80" placeholder="${tr('Misalnya: Aturan server','For example: Server rules')}"></label><button class="f-outline" type="button" id="msSaveTemplate">${tr('SIMPAN TEMPLATE','SAVE TEMPLATE')}</button></div></div><div class="ms-action-section"><div class="ms-action-heading"><strong>${tr('Kirim pesan','Send message')}</strong><small>${tr('Periksa preview dan channel tujuan sebelum mengirim.','Check the preview and destination channel before sending.')}</small></div><div class="ms-send-actions"><button class="f-primary" type="button" id="msSend">${tr('KIRIM KE DISCORD ↗','SEND TO DISCORD ↗')}</button><button class="f-primary" type="button" id="msUpdate" hidden>${tr('SIMPAN PERUBAHAN ↗','SAVE CHANGES ↗')}</button><button class="f-outline" type="button" id="msTest">${tr('KIRIM UJI','SEND TEST')}</button><button class="f-outline" type="button" id="msSendCopy" hidden>${tr('KIRIM SALINAN','SEND COPY')}</button></div></div><div class="ms-action-section ms-danger-section" id="msManageMessage" hidden><div class="ms-action-heading"><strong>${tr('Kelola pesan tercatat','Manage recorded message')}</strong><small>${tr('Hapus pesan dari Discord, atau lepas riwayat tanpa menghapus pesan. Tombol respons dan menu interaktif tidak lagi aktif setelah riwayat dilepas.','Delete the Discord message, or remove its history without deleting it. Response buttons and interactive menus stop working when history is removed.')}</small></div><div class="ms-send-actions"><button class="f-outline ms-danger-button" type="button" id="msDeleteMessage" hidden>${tr('HAPUS PESAN','DELETE MESSAGE')}</button><button class="f-outline" type="button" id="msForgetMessage" hidden>${tr('LEPAS RIWAYAT','REMOVE HISTORY')}</button></div></div></section><p class="f-muted ms-status" id="msStatus" aria-live="polite"></p><details class="ms-warning ms-recurring" id="msRecurringPanel"><summary>${tr('Pesan berkala','Recurring messages')}</summary><p>${tr('Simpan dan tinjau template terlebih dahulu. Jadwal memakai salinan template, channel dan mode pengirim yang dipilih di editor. Jadwal terlewat saat bot offline dilewati; tanggal 29–31 dilewati pada bulan yang tidak memilikinya. Jika hasil tidak pasti atau gagal, jadwal berhenti sampai diperiksa. Pesan yang sudah terkirim tidak dihapus.','Save and review the template first. Schedules use a copy of the template, channel and sender mode selected in the editor. Slots missed while the bot is offline are skipped; days 29–31 are skipped in months without them. If the result is uncertain or fails, the schedule stops until reviewed. Sent messages are not deleted.')}</p><div id="msRecurringForm"></div><p id="msRecurringStatus" role="status"></p><button class="f-outline" type="button" id="msRecurringRefresh">${tr('MUAT JADWAL BERKALA','LOAD RECURRING SCHEDULES')}</button><div id="msRecurringList" aria-live="polite"></div></details><details class="ms-warning ms-jobs"><summary>${tr('Pesan terjadwal','Scheduled messages')}</summary><p>${tr('Status tidak pasti mungkin sudah terkirim: periksa Discord sebelum menghapus atau menjadwalkan ulang. Menghapus riwayat tidak menarik pesan yang sudah terkirim.','An uncertain message may already have been sent: check Discord before deleting or rescheduling. Deleting history does not retract sent messages.')}</p><button class="f-outline" type="button" id="msJobsRefresh">${tr('MUAT JADWAL','LOAD SCHEDULE')}</button><div id="msJobs" aria-live="polite"></div></details></section></div>`;}
 function libraryMarkup(){return `<div class="ms-library-grid" id="messageStudioLibrary"><section class="f-panel"><div class="f-panel-head"><div><h2>${tr('Template tersimpan','Saved templates')}</h2><p>${tr('Dokumen container yang dapat dibuka, disunting, diduplikasi, dan dihapus.','Container documents that can be opened, edited, duplicated and deleted.')}</p></div><span>◇</span></div><div id="msTemplates" class="ms-library-list"><p class="ms-empty">${tr('Memuat…','Loading…')}</p></div></section><section class="f-panel"><div class="f-panel-head"><div><h2>${tr('Pesan terkirim','Sent messages')}</h2><p>${tr('Riwayat ini menampilkan channel dan pengirim, bukan nama template. Hanya pesan dari Message Studio yang dapat diedit atau dihapus di sini.','This history shows the channel and sender, not the template name. Only Message Studio messages can be edited or deleted here.')}</p></div><span>↗</span></div><div id="msMessages" class="ms-library-list"><p class="ms-empty">${tr('Memuat…','Loading…')}</p></div></section></div>`;}
 function firstSelection(doc){return doc.containers?.length?{kind:'block',container:0,block:0}:{kind:'outside',zone:list(doc.before).length?'before':'after',block:0};}
 function loadTemplate(template){state.doc=clone(template.document);state.templateId=template.id;state.messageId=null;state.templateName=template.name;state.uploads.clear();state.selection=firstSelection(state.doc);state.status=tr(`Template “${template.name}” dimuat.`,`Template “${template.name}” loaded.`);location.hash='#features/message-studio/editor';}
 function loadMessage(message){state.doc=clone(message.document);state.templateId=null;state.messageId=message.id;state.templateName='';state.delivery={channelId:message.channelId,sender:message.sender,identity:{name:message.identity?.name||'',avatarUrl:message.identity?.avatarUrl||''}};state.uploads.clear();state.selection=firstSelection(state.doc);state.status=tr(`Mengedit pesan ${message.test?'uji ':''}yang tercatat.`,`Editing recorded ${message.test?'test ':''}message.`);location.hash='#features/message-studio/editor';}
 function drawLibrary(root){const templates=$('#msTemplates',root),messages=$('#msMessages',root);if(!templates||!messages)return;templates.replaceChildren();messages.replaceChildren();const ts=list(state.data?.templates),ms=list(state.data?.messages);if(!ts.length)templates.append(el('p',{className:'ms-empty',text:tr('Belum ada template.','No templates yet.')}));for(const template of ts){const item=el('article',{className:'ms-library-item'},el('h3',{text:template.name}),el('p',{text:`${tr('Diperbarui','Updated')} ${new Date(template.updatedAt).toLocaleString(tr('id-ID','en-US'),{hour12:false})}`}),el('div',{className:'ms-inline-actions'},button(tr('BUKA','OPEN'),'f-outline',()=>loadTemplate(template),tr(`Buka template ${template.name} (ID ${template.id})`,`Open template ${template.name} (ID ${template.id})`)),button(tr('HAPUS','DELETE'),'ms-mini',async()=>{if(!(await (window.ZentixDialog ? window.ZentixDialog.confirm(tr(`Hapus template “${template.name}”?`,`Delete template “${template.name}”?`)) : Promise.resolve(window.confirm(tr(`Hapus template “${template.name}”?`,`Delete template “${template.name}”?`))))))return;try{await request(`/templates/${encodeURIComponent(template.id)}`,{method:'DELETE',body:{confirmed:true}});await reload(root,'library');}catch(error){await (window.ZentixDialog ? window.ZentixDialog.alert(error.message) : Promise.resolve(window.alert(error.message)));}},tr(`Hapus template ${template.name} (ID ${template.id})`,`Delete template ${template.name} (ID ${template.id})`))));templates.append(item);}if(!ms.length)messages.append(el('p',{className:'ms-empty',text:tr('Belum ada pesan yang tercatat.','No messages recorded yet.')}));for(const message of ms){const title=`# ${message.channelName||message.channelId} · ${message.sender==='webhook'?'Webhook':'ZentixBot'}${message.test?tr(' · UJI',' · TEST'):''}`;const actions=[button('EDIT','f-outline',()=>loadMessage(message),tr(`Edit pesan ${title} (ID ${message.id})`,`Edit message ${title} (ID ${message.id})`)),button(tr('HAPUS','DELETE'),'ms-mini',async()=>{if(!(await (window.ZentixDialog ? window.ZentixDialog.confirm(tr('Hapus pesan ini dari Discord? Tindakan tidak dapat dibatalkan.','Delete this message from Discord? This cannot be undone.')) : Promise.resolve(window.confirm(tr('Hapus pesan ini dari Discord? Tindakan tidak dapat dibatalkan.','Delete this message from Discord? This cannot be undone.'))))))return;try{await request(`/messages/${encodeURIComponent(message.id)}`,{method:'DELETE',body:{confirmed:true}});await reload(root,'library');}catch(error){await (window.ZentixDialog ? window.ZentixDialog.alert(error.message) : Promise.resolve(window.alert(error.message)));}},tr(`Hapus pesan ${title} (ID ${message.id})`,`Delete message ${title} (ID ${message.id})`))];if(message.url){const link=el('a',{href:message.url,target:'_blank',rel:'noopener noreferrer',className:'ms-mini',text:tr('BUKA DISCORD','OPEN DISCORD')});link.setAttribute('aria-label',tr(`Buka pesan ${title} di Discord (ID ${message.id})`,`Open message ${title} in Discord (ID ${message.id})`));actions.push(link);}messages.append(el('article',{className:'ms-library-item'},el('h3',{text:title}),el('p',{text:`${tr('Dikirim','Sent')} ${new Date(message.createdAt).toLocaleString(tr('id-ID','en-US'),{hour12:false})}`}),el('div',{className:'ms-inline-actions'},...actions)));}}
 function setBusy(root,busy){for(const node of root.querySelectorAll('#msSaveTemplate,#msTest,#msSend,#msUpdate,#msSendCopy,#msDeleteMessage,#msForgetMessage'))node.disabled=busy;}
 async function saveTemplate(root){if(invalidFlowDocument()){setStatus(root,tr('JSON cabang flow belum valid.','Flow branch JSON is not valid yet.'));return;}const name=$('#msTemplateName',root).value.trim();if(!name){setStatus(root,tr('Isi nama template terlebih dahulu.','Enter a template name first.'));return;}setBusy(root,true);try{const path=state.templateId?`/templates/${encodeURIComponent(state.templateId)}`:'/templates';const result=await request(path,{method:state.templateId?'PATCH':'POST',body:{name,document:state.doc,uploads:documentUploads()}});state.templateId=result.template.id;state.templateName=result.template.name;state.doc=clone(result.template.document);state.uploads.clear();setStatus(root,tr('Template tersimpan.','Template saved.'));await reload(root,'editor');}catch(error){setStatus(root,error.message);}finally{setBusy(root,false);}}
 async function send(root,test=false,copy=false){if(invalidFlowDocument()){setStatus(root,tr('JSON cabang flow belum valid.','Flow branch JSON is not valid yet.'));return;}if(!documentValidLocally()){setStatus(root,tr('Dokumen belum valid.','Document is not valid yet.'));return;}const channelId=state.delivery.channelId;if(!channelId){setStatus(root,tr('Pilih channel tujuan.','Choose a destination channel.'));return;}const action=test?tr('mengirim pesan uji','send a test message'):copy?tr('mengirim salinan','send a copy'):tr('mengirim pesan','send a message');if(!(await (window.ZentixDialog ? window.ZentixDialog.confirm(tr(`Lanjut ${action} ke Discord?`,`Continue to ${action} to Discord?`)) : Promise.resolve(window.confirm(tr(`Lanjut ${action} ke Discord?`,`Continue to ${action} to Discord?`))))))return;setBusy(root,true);try{const result=await request('/send',{method:'POST',body:{confirmed:true,channelId,sender:state.delivery.sender,identity:state.delivery.sender==='webhook'?{name:state.delivery.identity.name,avatarUrl:state.delivery.identity.avatarUrl}:undefined,document:state.doc,uploads:documentUploads(),test}});state.doc=clone(result.message.document);state.uploads.clear();state.messageId=result.message.id;state.templateId=null;state.status=tr(`Pesan ${test?'uji ':''}terkirim dan tercatat.`,`${test?'Test message':'Message'} sent and recorded.`);await reload(root,'editor');}catch(error){setStatus(root,error.message+(error.uncertain?tr(' Jangan mengirim ulang sebelum memeriksa channel.',' Do not resend before checking the channel.'):''));}finally{setBusy(root,false);}}
 async function updateMessage(root){if(invalidFlowDocument()){setStatus(root,tr('JSON cabang flow belum valid.','Flow branch JSON is not valid yet.'));return;}if(!state.messageId)return; if(!(await (window.ZentixDialog ? window.ZentixDialog.confirm(tr('Simpan perubahan ini ke pesan Discord yang tercatat?','Save these changes to the recorded Discord message?')) : Promise.resolve(window.confirm(tr('Simpan perubahan ini ke pesan Discord yang tercatat?','Save these changes to the recorded Discord message?'))))))return;setBusy(root,true);try{const result=await request(`/messages/${encodeURIComponent(state.messageId)}`,{method:'PATCH',body:{confirmed:true,document:state.doc,uploads:documentUploads()}});state.doc=clone(result.message.document);state.uploads.clear();state.status=tr('Pesan Discord diperbarui.','Discord message updated.');await reload(root,'editor');}catch(error){setStatus(root,error.message+(error.uncertain?tr(' Periksa channel sebelum mencoba lagi.',' Check the channel before trying again.'):''));}finally{setBusy(root,false);}}
 async function deleteMessage(root){if(!state.messageId||!(await (window.ZentixDialog ? window.ZentixDialog.confirm(tr('Hapus pesan ini dari Discord? Tindakan tidak dapat dibatalkan.','Delete this message from Discord? This cannot be undone.')) : Promise.resolve(window.confirm(tr('Hapus pesan ini dari Discord? Tindakan tidak dapat dibatalkan.','Delete this message from Discord? This cannot be undone.'))))))return;setBusy(root,true);try{await request(`/messages/${encodeURIComponent(state.messageId)}`,{method:'DELETE',body:{confirmed:true}});state.messageId=null;state.status=tr('Pesan dihapus dari Discord dan riwayat.','Message deleted from Discord and history.');await reload(root,'editor');}catch(error){setStatus(root,error.message+(error.uncertain?tr(' Periksa channel sebelum mencoba lagi.',' Check the channel before trying again.'):''));}finally{setBusy(root,false);}}
